<?php
 namespace OSS\Model; use OSS\Core\OssException; class TaggingConfig implements XmlConfig { public function __construct() { $this->tags = array(); } public function getTags() { return $this->tags; } public function addTag($tag) { $this->tags[] = $tag; } public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (!isset($xml->TagSet) || !isset($xml->TagSet->Tag)) return; foreach ($xml->TagSet->Tag as $tag) { $this->addTag(new Tag($tag->Key, $tag->Value)); } } public function serializeToXml() { $xml = new \SimpleXMLElement('<?xml version="1.0" encoding="utf-8"?><Tagging></Tagging>'); $xmlTagSet = $xml->addChild('TagSet'); foreach ($this->tags as $tag) { $xmlTag = $xmlTagSet->addChild('Tag'); $xmlTag->addChild('Key', strval($tag->getKey())); $xmlTag->addChild('Value', strval($tag->getValue())); } return $xml->asXML(); } public function __toString() { return $this->serializeToXml(); } private $tags = array(); }